    Pw = rng.uniform([-<span class="hljs-number">1</span>, -<span class="hljs-number">1</span>, <span class="hljs-number">4</span>], [<span class="hljs-number">1</span>, <span class="hljs-number">1</span>, <span class="hljs-number">8</span>], (<span class="hljs-number">200</span>, <span class="hljs-number">3</span>)); rvec = np.array([<span class="hljs-number">0.1</span>, -<span class="hljs-number">0.2</span>, <span class="hljs-number">0.05</span>]); tvec = np.array([<span class="hljs-number">0.2</span>, -<span class="hljs-number">0.1</span>, <span class="hljs-number">0.5</span>])
